import {create} from 'zustand';
import {ILIST_HEADER_TASK, KEY_TASK, LIST_HEADER_TASK} from '../helper';
import {GroupTaskList, ITask} from './interface';

interface BoardStore {
  listHeaderTask: ILIST_HEADER_TASK[];
  keyTaskSelect: KEY_TASK;
  groupTaskList: GroupTaskList[];
  isChangeStatusOfListTask: boolean;
  setListHeaderTask: (listHeaderTask: ILIST_HEADER_TASK[]) => void;
  addListHeaderTaskByKey: (child: ITask[], key: KEY_TASK) => void;
  changeListTasksDetail: (tasks: any[], key: KEY_TASK) => void;
  getListHeaderTask: () => ILIST_HEADER_TASK[];
  setGroupTaskList: (groupTaskList: GroupTaskList[]) => void;
  setIsChangeStatusOfListTask: (value: boolean) => void;
}

const initialSettingState = {
  listHeaderTask: LIST_HEADER_TASK,
  keyTaskSelect: KEY_TASK['my-task'],
  groupTaskList: [],
  isChangeStatusOfListTask: false,
};

const useBoardStore = create<BoardStore>((set, get) => ({
  ...initialSettingState,
  setListHeaderTask: (listHeaderTask: ILIST_HEADER_TASK[]) => {
    set({listHeaderTask});
  },
  addListHeaderTaskByKey: (child: ITask[], key: KEY_TASK) => {
    const newListHeaderTask = get().listHeaderTask.map(header => ({
      ...header,
      child: header.key === key ? child : header.child,
    }));
    set({listHeaderTask: newListHeaderTask});
  },
  getListHeaderTask: () => get().listHeaderTask,
  changeListTasksDetail: (assignTaskList: any[], key: KEY_TASK) => {
    const newListHeaderTask = get().listHeaderTask.map(header => ({
      ...header,
      child: header.child?.map(task => {
        if (header.key === key) {
          return {
            ...task,
            assignTaskList: assignTaskList,
          };
        }
        return task;
      }),
    }));
    set({listHeaderTask: newListHeaderTask});
  },
  setGroupTaskList: (groupTaskList: GroupTaskList[]) => {
    set({groupTaskList: groupTaskList});
  },
  setIsChangeStatusOfListTask: (value: boolean) => {
    set({isChangeStatusOfListTask: value});
  },
}));

export default useBoardStore;
