import {createBottomTabNavigator} from '@react-navigation/bottom-tabs';
import {NavigationName} from '../../constants';
import DashboardScreen from '../../app/screens/dashboard';
import BoardScreen from '../../app/screens/board';
import TabBarETask from './TabBarETask';
import {useTranslation} from 'react-i18next';
import {useEffect} from 'react';
import {useETaskZutandStore} from '../../zutand/eTaskZutandStore';
import {useNotificationServices} from '../../hooks/useNotificationServices';
import NotificationScreen from '../../app/screens/notification';
const Tabs = createBottomTabNavigator();

const BottomTabNavigationETask = () => {
  const NotificationService = useNotificationServices();
  const {totalNotify} = useETaskZutandStore();
  const {t} = useTranslation();
  const {setTotalNotify} = useETaskZutandStore();
  const getNUmberOfNotiUnread = async () => {
    try {
      let res = await NotificationService.getListNotifications(
        {page: 0, size: 10, sort: 'createdDate,desc'},
        {status: 'unread', system: 'E_TASK'},
      );
      setTotalNotify(res.totalRecords);
    } catch (error) {
      console.error(error);
    }
  };
  useEffect(() => {
    getNUmberOfNotiUnread();
  }, []);
  return (
    <Tabs.Navigator
      screenOptions={{headerShown: false}}
      tabBar={props => (
        <TabBarETask {...props} t={t} totalRecoders={totalNotify} />
      )}>
      <Tabs.Screen
        name={NavigationName.Dashboard}
        component={DashboardScreen}
      />
      <Tabs.Screen name={NavigationName.Tasks} component={BoardScreen} />
      <Tabs.Screen
        name={NavigationName.Notification}
        component={NotificationScreen}
      />
    </Tabs.Navigator>
  );
};

export default BottomTabNavigationETask;
